@push('scripts')
<script>
document.querySelectorAll('#saved-monitoring-form tbody tr').forEach(row=>{const av=row.querySelector('.availability-select'),spec=row.querySelector('.spec-select'),method=row.querySelector('.breeding-method-select'),aiFields=row.querySelector('.breeding-ai-fields');function sync(){let unavailable=av.value==='unavailable';spec.disabled=unavailable;row.querySelector('.reason-select').disabled=!unavailable;row.querySelectorAll('.spec-fields').forEach(box=>{let active=box.dataset.spec===spec.value;box.classList.toggle('hidden',!active);box.querySelectorAll('input,select,textarea').forEach(el=>el.disabled=unavailable||!active)});if(aiFields){let active=spec.value==='breeding'&&method?.value==='AI'&&!unavailable;aiFields.classList.toggle('hidden',!active);aiFields.querySelectorAll('.breeding-ai-control').forEach(el=>{el.disabled=!active;el.required=active});}}av.addEventListener('change',sync);spec.addEventListener('change',sync);method?.addEventListener('change',sync);sync()});
</script>
